"""Español — sira (sira_001 … sira_150)."""

T = {
"sira_001": ("¿En qué ciudad nació el Profeta Muhammad ﷺ?", ["La Meca", "Medina", "Ta'if", "Jerusalén"], "El Profeta Muhammad ﷺ nació en La Meca, en el Hiyaz."),
"sira_002": ("¿Cómo se llama el año del nacimiento del Profeta ﷺ, marcado por el suceso del elefante?", ["El Año del Elefante", "El Año de la Victoria", "El Año del Camello", "El Año de la Luz"], "El suceso del elefante, en el que Allah protegió la Ka'ba, se narra en la sura Al-Fil."),
"sira_003": ("¿Cómo se llamaba la primera esposa del Profeta ﷺ?", ["Jadiya", "Aisha", "Hafsa", "Zaynab"], "Jadiya bint Juwaylid fue la primera esposa del Profeta ﷺ y la primera persona en creer en su mensaje."),
"sira_004": ("¿En qué cueva recibió el Profeta ﷺ la primera revelación?", ["La cueva de Hira", "La cueva de Zawr", "La cueva de los Compañeros", "La cueva de Uhud"], "La primera revelación tuvo lugar en la cueva de Hira, en el Yabal an-Nur, cerca de La Meca."),
"sira_005": ("¿Qué ángel trajo la revelación al Profeta ﷺ?", ["Yibril (Gabriel)", "Mika'il (Miguel)", "Israfil", "Malik"], "El Corán menciona explícitamente que Yibril trajo la revelación con el permiso de Allah."),
"sira_006": ("¿Cómo se llama la emigración del Profeta ﷺ y sus compañeros de La Meca a Medina?", ["La Hégira", "Al-Isra", "Al-Mi'ray", "Al-Fath"], "La Hégira es la histórica emigración a Medina, punto de partida del calendario islámico."),
"sira_007": ("¿A qué ciudad emigraron el Profeta ﷺ y Abu Bakr?", ["Medina", "Ta'if", "Damasco", "Jerusalén"], "El Profeta ﷺ y Abu Bakr emigraron de La Meca a Medina (entonces llamada Yazrib)."),
"sira_008": ("El Corán describe a un compañero como «el segundo de dos, cuando estaban en la cueva» durante la Hégira. ¿Quién era?", ["Abu Bakr", "Umar", "Uzman", "Ali"], "El Corán se refiere a Abu Bakr, que acompañó al Profeta ﷺ en la cueva de Zawr durante la Hégira."),
"sira_009": ("¿Qué batalla, mencionada en el Corán, vio a un pequeño ejército musulmán vencer a una fuerza mucho mayor?", ["La batalla de Badr", "La batalla de Uhud", "La batalla de la Trinchera", "La batalla de Hunayn"], "En Badr, Allah dio la victoria a un pequeño grupo de creyentes sobre un ejército mucho mayor."),
"sira_010": ("¿Cómo se llama el regreso, en gran parte pacífico, del Profeta ﷺ y sus compañeros a La Meca?", ["La conquista de La Meca (Fath Makka)", "La batalla de La Meca", "El asedio de La Meca", "La caída de La Meca"], "La conquista de La Meca se produjo en gran parte de forma pacífica, sin derramamiento de sangre generalizado."),
"sira_011": ("¿Cómo se llama el último sermón pronunciado por el Profeta ﷺ hacia el final de su vida?", ["El Sermón de Despedida", "El Sermón de La Meca", "El Sermón de la Cueva", "El Sermón de Badr"], "El Sermón de Despedida (Jutbat al-Wada') se pronunció durante la última peregrinación del Profeta ﷺ."),
"sira_012": ("¿En qué mes afirma el Corán que comenzó su revelación?", ["Ramadán", "Muharram", "Rayab", "Dhul-Hiyya"], "El Corán afirma que Ramadán es el mes en que fue revelado."),
"sira_013": ("¿Cuál era la profesión del Profeta ﷺ antes de recibir la revelación?", ["Comerciante", "Solo pastor", "Herrero", "Escriba"], "El Profeta ﷺ trabajó en el comercio, un hecho bien establecido de su biografía."),
"sira_014": ("¿Qué abuelo del Profeta ﷺ cuidó de él tras la muerte de su madre?", ["Abdul Muttalib", "Abu Talib", "Abu Lahab", "Abu Sufyan"], "Abdul Muttalib cuidó del joven Muhammad ﷺ tras la muerte de su madre Amina."),
"sira_015": ("¿Qué tío crió al Profeta ﷺ tras la muerte de su abuelo?", ["Abu Talib", "Al-Abbas", "Hamza", "Abu Lahab"], "Abu Talib se encargó de criar a su sobrino tras la muerte de Abdul Muttalib."),
"sira_016": ("¿Cómo se llama el viaje nocturno del Profeta ﷺ de La Meca a Jerusalén, mencionado en el Corán?", ["Al-Isra", "La Hégira", "Al-Fath", "Al-Gazwa"], "La sura Al-Isra comienza describiendo este milagroso viaje nocturno."),
"sira_017": ("¿Cuál de las hijas del Profeta ﷺ se casó con Ali ibn Abi Talib?", ["Fátima", "Zaynab", "Ruqayya", "Umm Kulzum"], "Fátima, hija del Profeta ﷺ y de Jadiya, se casó con Ali ibn Abi Talib, un hecho ampliamente establecido."),
"sira_018": ("¿Qué mes marca el inicio del año del calendario islámico, en referencia a la Hégira?", ["Muharram", "Ramadán", "Shawwal", "Dhul-Qa'da"], "El calendario islámico comienza con el mes de Muharram, tomando como referencia el año de la Hégira."),
"sira_019": ("¿Quién fue el primer almuédano del islam, elegido por el Profeta ﷺ para llamar a la oración?", ["Bilal ibn Rabah", "Abu Bakr", "Umar ibn al-Jattab", "Salman al-Farisi"], "Bilal, con su hermosa voz, fue elegido como primer almuédano del islam."),
"sira_020": ("¿Cuál fue la primera mezquita fundada por el Profeta ﷺ al llegar cerca de Medina?", ["La mezquita de Quba", "La mezquita Al-Haram", "La mezquita Al-Aqsa", "La mezquita de las dos qiblas"], "Al llegar a Quba, a las puertas de Medina, el Profeta ﷺ fundó allí la primera mezquita."),
"sira_021": ("¿Cómo se llamaba la madre del Profeta ﷺ?", ["Amina", "Jadiya", "Halima", "Fátima"], "Amina bint Wahb fue la madre del Profeta ﷺ; Halima fue su nodriza."),
"sira_022": ("¿Cómo se llamaba el padre del Profeta ﷺ, fallecido antes de su nacimiento?", ["Abdullah", "Abu Talib", "Abd al-Muttalib", "Hamza"], "Abdullah, hijo de Abd al-Muttalib, murió antes de que naciera su hijo Muhammad ﷺ."),
"sira_023": ("¿Qué apodo dieron los mecanos al Profeta ﷺ antes de la revelación, por su honestidad?", ["Al-Amin (el digno de confianza)", "Al-Faruq", "As-Siddiq", "Sayf Allah"], "Ya antes de la revelación lo llamaban al-Amin: la gente le confiaba sus bienes."),
"sira_024": ("¿En qué año de la Hégira tuvo lugar la conquista de La Meca?", ["Año 8", "Año 2", "Año 5", "Año 10"], "En el año 8 de la Hégira el Profeta ﷺ entró en La Meca casi sin combate y perdonó a su gente."),
"sira_025": ("¿En qué año de la Hégira realizó el Profeta ﷺ su Peregrinación de Despedida?", ["Año 10", "Año 6", "Año 8", "Año 12"], "La Peregrinación de Despedida tuvo lugar en el año 10; el Profeta ﷺ pronunció allí su último sermón."),
"sira_026": ("¿Cuántas hijas tuvo el Profeta ﷺ?", ["4", "1", "2", "7"], "Zaynab, Ruqayya, Umm Kulzum y Fátima: las cuatro hijas del Profeta ﷺ."),
"sira_027": ("¿Cómo se llama a los habitantes de Medina que acogieron y ayudaron a los musulmanes emigrados?", ["Los Ansar (los Auxiliares)", "Los Muhayirun", "Los Quraysh", "Los Tabi'un"], "Los Ansar, «los Auxiliares», compartieron sus casas y bienes con sus hermanos emigrados."),
"sira_028": ("¿Cómo se llama a los musulmanes que dejaron La Meca para emigrar a Medina?", ["Los Muhayirun (los Emigrados)", "Los Ansar", "Los Hunafa'", "Los Guzat"], "Los Muhayirun dejaron casas y bienes en La Meca para preservar su fe."),
"sira_029": ("¿En qué mes tuvo lugar la batalla de Badr?", ["Ramadán", "Muharram", "Dhul-Hiyya", "Rayab"], "La batalla de Badr tuvo lugar en Ramadán del año 2 de la Hégira."),
"sira_030": ("Antes de que la qibla se fijara hacia la Ka'ba, ¿hacia qué ciudad rezaban los musulmanes?", ["Jerusalén (Bayt al-Maqdis)", "Medina", "Ta'if", "Damasco"], "Los musulmanes rezaron primero hacia Bayt al-Maqdis; luego Allah ordenó volverse hacia la Mezquita Sagrada (Corán 2:142-144)."),
"sira_031": ("¿A qué tribu pertenecía el Profeta Muhammad ﷺ?", ["Quraysh", "Los Aws", "Los Jazray", "Zaqif"], "Una sura entera lleva el nombre de su tribu: Quraysh."),
"sira_032": ("¿De qué clan de Quraysh procedía el Profeta ﷺ?", ["Banu Hashim", "Banu Umayya", "Banu Majzum", "Banu Tamim"], "El Profeta ﷺ pertenecía a Banu Hashim, el clan de su bisabuelo Hashim."),
"sira_033": ("¿Cómo se llamaba la nodriza que amamantó al Profeta ﷺ en el desierto?", ["Halima as-Sa'diyya", "Amina", "Jadiya", "Fátima"], "Según la costumbre mecana, el niño fue confiado a una nodriza beduina: Halima as-Sa'diyya."),
"sira_034": ("¿Qué tío del Profeta ﷺ, héroe de Badr, cayó mártir en Uhud?", ["Hamza", "Abu Talib", "Al-Abbas", "Abu Lahab"], "Hamza ibn Abd al-Muttalib combatió en Badr y murió en la batalla de Uhud."),
"sira_035": ("¿Qué primo del Profeta ﷺ, criado en su casa, llegó a ser el cuarto califa?", ["Ali ibn Abi Talib", "Ya'far", "Aqil", "Al-Abbas"], "Ali, hijo de Abu Talib, creció con el Profeta ﷺ y fue el cuarto califa bien guiado."),
"sira_036": ("¿Quién fue el primer califa tras la muerte del Profeta ﷺ?", ["Abu Bakr", "Umar", "Uzman", "Ali"], "Abu Bakr as-Siddiq fue elegido primer califa."),
"sira_037": ("¿Qué título lleva Abu Bakr, por haber creído al Profeta ﷺ sin vacilar?", ["As-Siddiq (el Veraz)", "Al-Faruq", "Dhun-Nurayn", "Sayf Allah"], "Abu Bakr es llamado as-Siddiq, el que afirma y cree la verdad."),
"sira_038": ("¿Qué título lleva Umar ibn al-Jattab?", ["Al-Faruq (el que distingue la verdad de la falsedad)", "As-Siddiq", "Dhun-Nurayn", "Al-Amin"], "Umar es llamado al-Faruq, el que separa la verdad de la falsedad."),
"sira_039": ("¿Por qué se llama a Uzman ibn Affan «Dhun-Nurayn», el de las dos luces?", ["Se casó con dos hijas del Profeta ﷺ, una tras otra", "Llevaba dos lámparas", "Memorizó el Corán dos veces", "Hizo dos hégiras"], "Uzman se casó con Ruqayya y, tras su muerte, con Umm Kulzum, ambas hijas del Profeta ﷺ."),
"sira_040": ("¿En qué orden se sucedieron los cuatro califas bien guiados?", ["Abu Bakr, Umar, Uzman, Ali", "Ali, Umar, Abu Bakr, Uzman", "Umar, Abu Bakr, Ali, Uzman", "Abu Bakr, Ali, Umar, Uzman"], "Abu Bakr, luego Umar, luego Uzman, luego Ali."),
"sira_041": ("¿Quién fue la primera persona en creer en el mensaje del Profeta ﷺ?", ["Jadiya, su esposa", "Abu Bakr", "Ali", "Bilal"], "Jadiya creyó en él desde la primera revelación y lo apoyó."),
"sira_042": ("¿Quién compró a Bilal para liberarlo de las torturas de su amo?", ["Abu Bakr", "Umar", "Hamza", "Uzman"], "Abu Bakr compró a Bilal y lo liberó."),
"sira_043": ("¿Quién fue la primera mártir del islam, muerta en La Meca por su fe?", ["Sumayya, madre de Ammar", "Asma", "Umm Salama", "Safiyya"], "Sumayya bint Jayyat, madre de Ammar ibn Yasir, fue asesinada por Abu Yahl."),
"sira_044": ("¿A qué tierra tuvo lugar la primera emigración de musulmanes perseguidos en La Meca?", ["Abisinia (Etiopía)", "Persia", "Yemen", "Egipto"], "Los primeros emigrantes fueron a Abisinia, junto a un rey justo."),
"sira_045": ("¿Cómo se llamaba el rey de Abisinia que protegió a los musulmanes y por quien el Profeta ﷺ rezó la oración fúnebre en ausencia?", ["An-Nayashi (el Negus)", "Heraclio", "Cosroes", "Al-Muqawqis"], "El Profeta ﷺ anunció la muerte del Negus el mismo día y rezó por él con los compañeros."),
"sira_046": ("¿Qué compañero habló ante el Negus para explicar el islam?", ["Ya'far ibn Abi Talib", "Uzman", "Bilal", "Mus'ab ibn Umayr"], "Ya'far explicó al rey lo que enseñaba el Profeta ﷺ y le recitó versículos de la sura Maryam."),
"sira_047": ("¿Qué tío del Profeta ﷺ es condenado por su nombre en el Corán?", ["Abu Lahab", "Abu Talib", "Al-Abbas", "Hamza"], "«¡Perezcan las manos de Abu Lahab, y perezca él!»"),
"sira_048": ("¿Cómo se llama el año en que el Profeta ﷺ perdió a su esposa Jadiya y a su tío Abu Talib?", ["El Año de la Tristeza", "El Año del Elefante", "El Año de las Delegaciones", "El Año del Hambre"], "Los dos grandes apoyos del Profeta ﷺ murieron el mismo año, conocido como el Año de la Tristeza."),
"sira_049": ("¿En qué ciudad fue expulsado y herido el Profeta ﷺ tras llamar al islam, antes de negarse a que el ángel de las montañas aplastara a su gente?", ["At-Ta'if", "Medina", "Jaybar", "Tabuk"], "Rechazado en Ta'if, se negó a destruir a su gente, esperando que sus descendientes adoraran a Allah."),
"sira_050": ("Durante el Viaje Nocturno y la Ascensión (Isra y Mi'ray), ¿qué obligación se prescribió a los musulmanes?", ["Las cinco oraciones diarias", "El ayuno de Ramadán", "El zakat", "La peregrinación"], "Las oraciones se prescribieron esa noche, reducidas de cincuenta a cinco, con la recompensa de cincuenta."),
"sira_051": ("¿Qué árbol, en el límite extremo, vio el Profeta ﷺ durante la Ascensión, según la sura An-Naym?", ["Sidrat al-Muntaha", "El olivo bendito", "La palmera de Maryam", "El árbol de Tuba"], "«Junto a Sidrat al-Muntaha», el azufaifo del límite extremo."),
"sira_052": ("¿Cómo se llaman los juramentos de lealtad que gente de Yazrib prestó al Profeta ﷺ antes de la Hégira?", ["Los juramentos de Al-Aqaba", "El pacto de Hudaybiyya", "El juramento del árbol", "La Constitución de Medina"], "Gente de Yazrib juró lealtad al Profeta ﷺ en Al-Aqaba, cerca de Mina, antes de la Hégira."),
"sira_053": ("¿Qué compañero envió el Profeta ﷺ a Yazrib, antes de la Hégira, para enseñar el islam?", ["Mus'ab ibn Umayr", "Bilal", "Abu Hurayra", "Jalid ibn al-Walid"], "Mus'ab ibn Umayr fue el primer enviado a Yazrib, enseñando el Corán a los nuevos musulmanes."),
"sira_054": ("¿Quién durmió en la cama del Profeta ﷺ la noche en que partió para la Hégira?", ["Ali ibn Abi Talib", "Abu Bakr", "Zayd ibn Hariza", "Bilal"], "Ali ocupó su lugar en la cama para engañar a los vigilantes, y luego devolvió los depósitos a los mecanos."),
"sira_055": ("¿En qué cueva se escondieron el Profeta ﷺ y Abu Bakr durante la Hégira?", ["La cueva de Zawr", "La cueva de Hira", "La cueva de Uhud", "La cueva de Ta'if"], "Se escondieron tres días en la cueva de Zawr, al sur de La Meca."),
"sira_056": ("¿Qué hija de Abu Bakr llevó provisiones a la cueva y fue apodada «la de los dos cinturones»?", ["Asma", "Aisha", "Umm Kulzum", "Umm Ruman"], "Asma partió su cinturón en dos para atar las provisiones: de ahí «Dhat an-Nitaqayn»."),
"sira_057": ("¿Qué le pasó a Suraqa, que persiguió al Profeta ﷺ durante la Hégira?", ["Su caballo se hundió en la tierra y pidió seguridad", "Alcanzó al Profeta ﷺ", "Se perdió en el desierto", "Cayó enfermo"], "Las patas de su caballo se hundieron en la tierra; Suraqa pidió salvoconducto y se fue sin hacer daño."),
"sira_058": ("¿Cuál era el antiguo nombre de Medina, mencionado en el Corán?", ["Yazrib", "Tayba", "Jaybar", "Bakka"], "«Oh gente de Yazrib…», dice el Corán, recordando la batalla de los coaligados."),
"sira_059": ("¿Cómo se llamaba la camella del Profeta ﷺ, que se arrodilló en Hudaybiyya?", ["Al-Qaswa", "Al-Buraq", "Ad-Duldul", "Al-Adba"], "En Hudaybiyya, Al-Qaswa se arrodilló; el Profeta ﷺ dijo: «Quien detuvo al elefante la ha detenido»."),
"sira_060": ("¿Qué estableció el Profeta ﷺ entre los Muhayirun y los Ansar al llegar a Medina?", ["Una hermandad, de dos en dos", "Un impuesto", "Un ejército", "Un mercado"], "Hermanó a los emigrados con los auxiliares, cada Muhayir con un hermano de los Ansar."),
"sira_061": ("¿Cómo se llama el documento con el que el Profeta ﷺ organizó las relaciones entre las comunidades de Medina?", ["La Sahifa (Constitución) de Medina", "El tratado de Hudaybiyya", "El pacto de Ta'if", "La carta de Quba"], "La Sahifa fijó los derechos y deberes de los musulmanes y de las demás tribus de Medina."),
"sira_062": ("¿Cómo se llamaba a los compañeros pobres que vivían en la mezquita del Profeta ﷺ?", ["Ahl as-Suffa (la gente del banco)", "Los Muhayirun", "Los Ansar", "Los Hawariyyun"], "Abu Hurayra cuenta que estuvo entre la gente de la Suffa, alimentada por el Profeta ﷺ."),
"sira_063": ("¿Cuántos años después de la Hégira tuvo lugar la batalla de Badr?", ["Dos", "Cinco", "Ocho", "Diez"], "Badr se libró en el año 2 de la Hégira, durante Ramadán."),
"sira_064": ("¿Cuántos ángeles prometió Allah enviar como refuerzo a los creyentes en Badr?", ["Mil", "Cien", "Diez", "Cien mil"], "«Os reforzaré con mil ángeles, uno tras otro.»"),
"sira_065": ("En Uhud, ¿qué error de los arqueros cambió el curso de la batalla?", ["Abandonaron la colina pese a la orden del Profeta ﷺ", "Dispararon demasiado pronto", "Se durmieron", "Cambiaron de bando"], "El Profeta ﷺ había ordenado a los arqueros no moverse; la mayoría bajó por el botín y la caballería enemiga los rodeó."),
"sira_066": ("¿Cerca de qué ciudad está el monte Uhud?", ["Medina", "La Meca", "Ta'if", "Jerusalén"], "El monte Uhud está al norte de Medina; la batalla tuvo lugar a sus pies."),
"sira_067": ("¿Qué compañero propuso cavar una trinchera para defender Medina de los coaligados?", ["Salman al-Farisi", "Bilal", "Abu Dharr", "Suhayb"], "Salman el Persa propuso la trinchera, una táctica conocida en Persia."),
"sira_068": ("¿Con qué otro nombre se conoce la batalla de la Trinchera, según la sura que habla de ella?", ["La batalla de los Coaligados (Al-Ahzab)", "La batalla de Badr", "La batalla de Hunayn", "La batalla de Mu'ta"], "La sura Al-Ahzab recuerda los ejércitos aliados que sitiaron Medina y el viento enviado contra ellos."),
"sira_069": ("¿Cómo se llama el juramento prestado bajo un árbol en Hudaybiyya, con el que Allah dice estar complacido?", ["Bay'at ar-Ridwan", "Bay'at al-Aqaba", "Bay'at an-Nisa", "Bay'at al-Fath"], "«Allah se complació con los creyentes cuando te juraron lealtad bajo el árbol.»"),
"sira_070": ("¿Qué sura comienza con «Te hemos dado una victoria clara», revelada tras el tratado de Hudaybiyya?", ["Al-Fath", "An-Nasr", "Al-Anfal", "At-Tawba"], "«Ciertamente, te hemos dado una victoria clara»: la sura Al-Fath."),
"sira_071": ("¿En qué año de la Hégira se concluyó el tratado de Hudaybiyya?", ["Año 6", "Año 2", "Año 8", "Año 10"], "El tratado de Hudaybiyya se concluyó en el año 6 entre los musulmanes y Quraysh."),
"sira_072": ("¿Qué emperador bizantino recibió la carta del Profeta ﷺ invitándolo al islam e interrogó a Abu Sufyan sobre él?", ["Heraclio", "Nerón", "Constantino", "Justiniano"], "Heraclio interrogó a Abu Sufyan sobre el Profeta ﷺ tras recibir su carta."),
"sira_073": ("¿A quién entregó el Profeta ﷺ el estandarte en Jaybar, tras decir: «Mañana se lo daré a un hombre a quien Allah y Su Mensajero aman»?", ["Ali ibn Abi Talib", "Abu Bakr", "Umar", "Sa'd ibn Abi Waqqas"], "Llamó a Ali, que tenía los ojos enfermos; le aplicó su saliva, lo curó y le dio el estandarte."),
"sira_074": ("¿Qué tres comandantes cayeron uno tras otro en la batalla de Mu'ta?", ["Zayd ibn Hariza, Ya'far ibn Abi Talib y Abdullah ibn Rawaha", "Hamza, Mus'ab y Sa'd", "Abu Bakr, Umar y Uzman", "Bilal, Salman y Suhayb"], "El Profeta ﷺ anunció en Medina: «Zayd tomó el estandarte y cayó, luego Ya'far, luego Ibn Rawaha… luego lo tomó una espada de Allah»."),
"sira_075": ("¿A qué compañero llamó el Profeta ﷺ «una espada entre las espadas de Allah»?", ["Jalid ibn al-Walid", "Ali", "Hamza", "Abu Ubayda"], "En Mu'ta, «una espada entre las espadas de Allah», Jalid ibn al-Walid, tomó el estandarte y salvó al ejército."),
"sira_076": ("¿Qué hizo el Profeta ﷺ con los ídolos que rodeaban la Ka'ba en la conquista de La Meca?", ["Los derribó recitando «Ha venido la verdad y se ha desvanecido la falsedad»", "Los vendió", "Los llevó a Medina", "Los dejó en su sitio"], "Golpeó los ídolos con su bastón diciendo: «Ha venido la verdad y se ha desvanecido la falsedad»."),
"sira_077": ("¿Quién hizo la llamada a la oración desde lo alto de la Ka'ba el día de la conquista de La Meca?", ["Bilal", "Abu Bakr", "Ali", "Umar"], "El Profeta ﷺ ordenó a Bilal subir a la Ka'ba y llamar a la oración."),
"sira_078": ("¿Qué dijo el Profeta ﷺ a los mecanos vencidos que lo habían perseguido, el día de la conquista?", ["«Id, sois libres»", "«Seréis juzgados mañana»", "«Abandonad la ciudad»", "«Pagad un rescate»"], "Los perdonó: «Id, sois libres»."),
"sira_079": ("¿En qué batalla, nombrada en el Corán, fueron los musulmanes sorprendidos al principio pese a su gran número?", ["Hunayn", "Badr", "Uhud", "Jaybar"], "«El día de Hunayn, vuestro gran número os complació, pero de nada os sirvió.»"),
"sira_080": ("¿Qué compañero, que no acudió a la expedición de Tabuk, confesó con honestidad y fue perdonado por una revelación?", ["Ka'b ibn Malik", "Abu Dharr", "Anas ibn Malik", "Abu Hurayra"], "Ka'b ibn Malik dijo la verdad, soportó cincuenta días de aislamiento y luego Allah reveló su perdón (9:118)."),
"sira_081": ("¿Cómo se llama el año 9 de la Hégira, en que muchas tribus vinieron a Medina para abrazar el islam?", ["El Año de las Delegaciones", "El Año de la Tristeza", "El Año del Elefante", "El Año de la Sequía"], "Tras la conquista de La Meca, las delegaciones de tribus árabes afluyeron a Medina."),
"sira_082": ("¿Dónde pronunció el Profeta ﷺ su Sermón de Despedida?", ["En Arafat", "En Medina", "En el monte Uhud", "En Ta'if"], "El Sermón de Despedida se pronunció en Arafat, durante la Peregrinación de Despedida."),
"sira_083": ("¿Qué versículo, revelado durante la Peregrinación de Despedida, anuncia que la religión ha sido perfeccionada?", ["«Hoy he perfeccionado para vosotros vuestra religión»", "«Lee, en el nombre de tu Señor»", "«Cuando llegue el auxilio de Allah»", "«Di: Él es Allah, Uno»"], "«Hoy he perfeccionado para vosotros vuestra religión y he completado Mi gracia sobre vosotros.»"),
"sira_084": ("¿En qué ciudad murió y fue enterrado el Profeta ﷺ?", ["Medina", "La Meca", "Jerusalén", "Ta'if"], "Murió en Medina en el año 11 de la Hégira y fue enterrado allí."),
"sira_085": ("¿En la habitación de qué esposa fue enterrado el Profeta ﷺ?", ["De Aisha", "De Jadiya", "De Hafsa", "De Umm Salama"], "Fue enterrado donde murió, en la habitación de Aisha, hoy dentro de la Mezquita del Profeta."),
"sira_086": ("¿Quién declaró, a la muerte del Profeta ﷺ: «Quien adoraba a Muhammad, Muhammad ha muerto; quien adora a Allah, Allah es el Viviente»?", ["Abu Bakr", "Umar", "Ali", "Bilal"], "Abu Bakr calmó a los compañeros y recitó: «Muhammad no es sino un mensajero…» (3:144)."),
"sira_087": ("¿Cómo se llamaban los dos nietos del Profeta ﷺ, hijos de Fátima y Ali?", ["Al-Hasan y Al-Husayn", "Ibrahim e Isma'il", "Zayd y Usama", "Ya'far y Aqil"], "Al-Hasan y Al-Husayn, a quienes el Profeta ﷺ amaba tiernamente."),
"sira_088": ("¿Qué esposa del Profeta ﷺ era hija de Abu Bakr?", ["Aisha", "Hafsa", "Zaynab", "Sawda"], "Aisha, hija de Abu Bakr, transmitió un gran número de hadices."),
"sira_089": ("¿Qué esposa del Profeta ﷺ era hija de Umar ibn al-Jattab?", ["Hafsa", "Aisha", "Umm Habiba", "Maymuna"], "Hafsa bint Umar; la primera copia recopilada del Corán se guardó con ella."),
"sira_090": ("¿Qué compañero narró el mayor número de hadices del Profeta ﷺ?", ["Abu Hurayra", "Anas ibn Malik", "Abdullah ibn Umar", "Yabir"], "Abu Hurayra, que acompañó de cerca al Profeta ﷺ, es el compañero que más hadices narró."),
"sira_091": ("¿Qué joven compañero sirvió al Profeta ﷺ durante diez años sin oír jamás un reproche?", ["Anas ibn Malik", "Usama ibn Zayd", "Ibn Abbas", "Zayd ibn Zabit"], "Anas dijo: «Serví al Profeta ﷺ diez años; nunca me dijo “uf”, ni “¿por qué hiciste eso?”»."),
"sira_092": ("¿Por qué joven primo rezó el Profeta ﷺ: «Oh Allah, enséñale el Libro»?", ["Abdullah ibn Abbas", "Ali", "Ya'far", "Usama"], "El Profeta ﷺ abrazó a Ibn Abbas y dijo: «Oh Allah, enséñale el Libro»."),
"sira_093": ("¿Qué compañero envió el Profeta ﷺ a Yemen, diciéndole que llamara primero a la unicidad de Allah?", ["Mu'adh ibn Yabal", "Bilal", "Abu Musa solo", "Zayd ibn Hariza"], "«Vas a un pueblo de la Gente del Libro: llámalos primero a testimoniar que no hay dios sino Allah…»"),
"sira_094": ("¿A qué compañero llamó el Profeta ﷺ «el hombre de confianza (amin) de esta comunidad»?", ["Abu Ubayda ibn al-Yarrah", "Abu Bakr", "Uzman", "Jalid"], "«Cada comunidad tiene un hombre de confianza, y el de esta comunidad es Abu Ubayda ibn al-Yarrah.»"),
"sira_095": ("¿Qué compañero, escriba de la revelación, fue encargado por Abu Bakr de recopilar el Corán?", ["Zayd ibn Zabit", "Abu Hurayra", "Anas ibn Malik", "Salman"], "Tras la batalla de al-Yamama, Abu Bakr encargó a Zayd ibn Zabit recopilar el Corán."),
"sira_096": ("¿Bajo qué califa se enviaron copias oficiales del Corán a las provincias?", ["Uzman ibn Affan", "Abu Bakr", "Umar", "Ali"], "Uzman hizo copiar el mushaf y envió un ejemplar a cada provincia."),
"sira_097": ("¿De qué tierra venía el compañero Salman, llamado «al-Farisi»?", ["Persia", "Abisinia", "Bizancio", "Yemen"], "Salman al-Farisi, «el Persa», vino de Persia en busca de la verdad."),
"sira_098": ("¿Qué compañero, venido de tierras bizantinas, es llamado «ar-Rumi»?", ["Suhayb", "Bilal", "Salman", "Abu Dharr"], "Suhayb ar-Rumi creció entre los bizantinos antes de abrazar el islam en La Meca."),
"sira_099": ("¿Cómo se llama la mezquita del Profeta ﷺ en Medina?", ["Al-Masyid an-Nabawi", "Al-Masyid al-Haram", "Al-Masyid al-Aqsa", "Masyid Quba"], "La mezquita que fundó en Medina se llama la Mezquita del Profeta, al-Masyid an-Nabawi."),
"sira_100": ("¿Cuántas veces aparece el nombre «Muhammad» en el Corán?", ["Cuatro", "Una", "Doce", "Cien"], "En los versículos 3:144, 33:40, 47:2 y 48:29; el nombre «Ahmad» aparece en 61:6."),
"sira_101": ("¿Cómo describe el Corán al Profeta ﷺ para los creyentes, en el versículo 33:21?", ["Un excelente ejemplo", "Un juez severo", "Un rey", "Un poeta"], "«Ciertamente, tenéis en el Mensajero de Allah un excelente ejemplo.»"),
"sira_102": ("¿Cuál era la kunya (apodo paterno) del Profeta ﷺ?", ["Abu al-Qasim", "Abu Bakr", "Abu Abdullah", "Abu Talib"], "Lo llamaban Abu al-Qasim, por su hijo mayor Al-Qasim."),
"sira_103": ("¿Cómo se llamaba el hijo del Profeta ﷺ nacido en Medina, que murió siendo muy pequeño?", ["Ibrahim", "Al-Qasim", "Abdullah", "Al-Hasan"], "Ibrahim, nacido en Medina, murió siendo un bebé; el Profeta ﷺ lloró y dijo que el corazón se entristece sin decir lo que disgusta a Allah."),
"sira_104": ("¿Para quién condujo el Profeta ﷺ una caravana comercial a Siria antes de la revelación?", ["Jadiya", "Abu Bakr", "Abu Sufyan", "Al-Abbas"], "Jadiya, rica comerciante, le confió su caravana a Siria y luego le propuso matrimonio."),
"sira_105": ("¿Cómo resolvió el joven Muhammad ﷺ la disputa de los clanes sobre la colocación de la Piedra Negra?", ["La puso sobre un paño que cada clan levantó, y luego la colocó él mismo", "La llevó solo", "Echó a suertes", "La confió a Abu Bakr"], "Extendió un manto, puso la Piedra encima, hizo que los jefes de clan levantaran juntos el paño y la colocó con su propia mano."),
"sira_106": ("¿A qué edad recibió el Profeta ﷺ la primera revelación?", ["Cuarenta años", "Veinticinco", "Cincuenta", "Sesenta"], "La revelación comenzó cuando tenía cuarenta años, en la cueva de Hira."),
"sira_107": ("¿Ante qué primo de Jadiya, conocedor de las Escrituras, fue llevado el Profeta ﷺ tras la primera revelación?", ["Waraqa ibn Nawfal", "Abu Talib", "Abu Lahab", "Al-Walid"], "Waraqa dijo: «Es el Namus (el ángel) que Allah envió a Musa»."),
"sira_108": ("¿A qué colina subió el Profeta ﷺ para llamar públicamente a Quraysh, tras el versículo «Advierte a tus parientes más cercanos»?", ["As-Safa", "Uhud", "Arafat", "Hira"], "Subió a as-Safa, llamó a los clanes de Quraysh y les advirtió de un castigo severo."),
"sira_109": ("¿Qué califa estableció el calendario musulmán a partir del año de la Hégira?", ["Umar ibn al-Jattab", "Abu Bakr", "Uzman", "Ali"], "Bajo Umar, se eligió la Hégira como punto de partida del calendario."),
"sira_110": ("¿Cuántos años vivió el Profeta ﷺ en Medina tras la Hégira?", ["Diez", "Tres", "Veinte", "Trece"], "Vivió diez años en Medina, desde la Hégira hasta su muerte en el año 11."),
"sira_111": ("¿Durante cuántos años predicó el Profeta ﷺ en La Meca antes de la Hégira?", ["Trece", "Tres", "Diez", "Veintitrés"], "Trece años en La Meca y luego diez en Medina: veintitrés años de misión."),
"sira_112": ("¿Qué compañero poeta defendió al Profeta ﷺ con sus versos, y para quien pidió el apoyo de Yibril?", ["Hassan ibn Zabit", "Ka'b ibn Malik", "Abdullah ibn Rawaha", "Labid"], "El Profeta ﷺ dijo a Hassan: «Respóndeles, y Yibril está contigo»."),
"sira_113": ("¿De qué compañero dijo el Profeta ﷺ que se le había dado «una de las flautas de la familia de Dawud» por su bella recitación?", ["Abu Musa al-Ash'ari", "Bilal", "Ubayy ibn Ka'b", "Ibn Mas'ud"], "Al oírlo recitar, el Profeta ﷺ dijo que a Abu Musa se le había dado una de las flautas de la familia de Dawud."),
"sira_114": ("El Profeta ﷺ recomendó aprender el Corán de cuatro compañeros. ¿Cuál de estos era uno de ellos?", ["Abdullah ibn Mas'ud", "Abu Hurayra", "Anas ibn Malik", "Jalid ibn al-Walid"], "«Aprended el Corán de cuatro: Ibn Mas'ud, Salim, Mu'adh ibn Yabal y Ubayy ibn Ka'b.»"),
"sira_115": ("¿En qué batalla fue herido el Profeta ﷺ en el rostro y perdió un diente?", ["Uhud", "Badr", "Hunayn", "Jaybar"], "En Uhud, se le rompió un diente y fue herido en el rostro."),
"sira_116": ("¿A qué compañero, arquero en Uhud, dijo el Profeta ﷺ: «¡Dispara! Que mi padre y mi madre sean tu rescate»?", ["Sa'd ibn Abi Waqqas", "Talha", "Az-Zubayr", "Ali"], "El Profeta ﷺ le entregó flechas diciendo: «Dispara, que mi padre y mi madre sean sacrificados por ti»."),
"sira_117": ("¿Qué caravana salieron a interceptar los musulmanes, lo que llevó a la batalla de Badr?", ["La de Abu Sufyan, que volvía de Siria", "La del Negus", "La de los persas", "La de Ta'if"], "La caravana de Quraysh dirigida por Abu Sufyan escapó, pero el ejército mecano llegó a Badr."),
"sira_118": ("¿Cuándo abrazó el islam el jefe mecano Abu Sufyan?", ["En la conquista de La Meca", "Antes de la Hégira", "En Badr", "Tras la muerte del Profeta ﷺ"], "Abu Sufyan se convirtió en vísperas de la entrada del Profeta ﷺ en La Meca."),
"sira_119": ("¿Qué manantial brotó para Hayar y su hijo Isma'il en el valle de La Meca?", ["Zamzam", "El Nilo", "El Éufrates", "El Jordán"], "Un ángel golpeó el suelo y brotó el agua de Zamzam; Hayar hizo un cerco a su alrededor."),
"sira_120": ("¿Qué estaba grabado en el anillo del Profeta ﷺ?", ["«Muhammad Rasul Allah»", "«Allahu Akbar»", "«La ilaha illa Allah»", "Solo su nombre"], "Su anillo de plata llevaba «Muhammad, Mensajero de Allah» en tres líneas."),
"sira_121": ("¿Qué alimentos le gustaban al Profeta ﷺ, según Aisha?", ["Los dulces y la miel", "El pescado", "Las especias fuertes", "Solo el vinagre"], "Aisha relata que el Profeta ﷺ amaba las cosas dulces y la miel."),
"sira_122": ("¿Qué día de la semana nació el Profeta ﷺ, día en que también ayunaba?", ["Lunes", "Viernes", "Sábado", "Miércoles"], "Preguntado por el ayuno del lunes, dijo: «Es el día en que nací y el día en que me llegó la revelación»."),
"sira_123": ("¿Dónde estaba el «sello de la profecía» en el cuerpo del Profeta ﷺ?", ["Entre los hombros", "En la mano", "En la frente", "En el pecho"], "El sello de la profecía estaba entre sus hombros."),
"sira_124": ("¿De qué madera hizo un carpintero el minbar (púlpito) del Profeta ﷺ?", ["Tamarisco (azl)", "Cedro", "Olivo", "Palmera"], "El Profeta ﷺ hizo construir un minbar de madera de tamarisco, desde el que se dirigía a la gente."),
"sira_125": ("¿Qué dos grandes tribus de Medina formaron los Ansar?", ["Los Aws y los Jazray", "Quraysh y Zaqif", "Tamim y Hawazin", "Kinda y Hamdan"], "Los Aws y los Jazray, rivales de antiguo, se unieron en el islam y se convirtieron en los Ansar."),
"sira_126": ("¿Qué título da el Corán a las esposas del Profeta ﷺ?", ["Las Madres de los Creyentes", "Las reinas de Medina", "Las hijas de Quraysh", "Las guardianas del Libro"], "«Sus esposas son sus madres»: las Madres de los Creyentes."),
"sira_127": ("¿En qué año del calendario cristiano tuvo lugar la Hégira?", ["622", "570", "632", "610"], "La Hégira, en 622, marca el inicio del calendario musulmán."),
"sira_128": ("¿Qué respondió Abd ar-Rahman ibn Awf cuando su hermano ansari le ofreció la mitad de sus bienes?", ["«Muéstrame el mercado»", "Lo aceptó todo", "Pidió una casa", "Se negó a hablar"], "Dijo: «Que Allah bendiga tus bienes y tu familia; solo muéstrame el mercado», y prosperó con el comercio."),
"sira_129": ("¿A qué compañero preguntó el Profeta ﷺ cuál es el versículo más grande del Corán, antes de felicitarlo por su respuesta (el Versículo del Trono)?", ["Ubayy ibn Ka'b", "Abu Bakr", "Zayd ibn Zabit", "Bilal"], "Ubayy respondió: «Allah, no hay dios sino Él, el Viviente…»; el Profeta ﷺ dijo: «¡Que el conocimiento te alegre, Abu al-Mundhir!»."),
"sira_130": ("¿Cómo se eligió el lugar de la mezquita del Profeta ﷺ en Medina?", ["Donde se arrodilló su camella", "Echando a suertes", "En el centro del mercado", "En el monte Uhud"], "Dejó a su camella caminar libremente: donde se arrodilló, se construyó la mezquita."),
"sira_131": ("¿Cuántos hijos varones tuvo el Profeta ﷺ, todos fallecidos de pequeños?", ["Tres", "Uno", "Cinco", "Ninguno"], "Al-Qasim y Abdullah, hijos de Jadiya, e Ibrahim, nacido en Medina."),
"sira_132": ("¿Qué compañero, liberado por el Profeta ﷺ y criado como un hijo, fue el padre de Usama?", ["Zayd ibn Hariza", "Bilal", "Salman", "Ammar"], "Zayd ibn Hariza, amado del Profeta ﷺ, fue el padre de Usama ibn Zayd."),
"sira_133": ("¿A qué joven compañero nombró el Profeta ﷺ al frente de un ejército poco antes de su muerte, pese a su juventud?", ["Usama ibn Zayd", "Anas ibn Malik", "Ibn Abbas", "Ibn Umar"], "El Profeta ﷺ dio el mando a Usama y respondió a quienes criticaban su edad que era digno de él, como su padre."),
"sira_134": ("¿Qué abuelo del Profeta ﷺ volvió a excavar el pozo de Zamzam, cegado desde hacía mucho?", ["Abd al-Muttalib", "Hashim", "Abd Manaf", "Qusayy"], "Abd al-Muttalib volvió a excavar Zamzam y se encargó de él para los peregrinos."),
"sira_135": ("¿Cuántas personas, aproximadamente, acompañaron al Profeta ﷺ en la batalla de Badr?", ["Poco más de trescientas", "Diez mil", "Mil", "Cincuenta"], "Los musulmanes en Badr eran poco más de trescientos, frente a un ejército mucho mayor."),
"sira_136": ("¿En qué mes del calendario musulmán nació el Profeta ﷺ?", ["Rabi' al-Awwal", "Ramadán", "Muharram", "Dhul-Hiyya"], "Nació en el mes de Rabi' al-Awwal, en el Año del Elefante."),
"sira_137": ("¿En qué mes llegó el Profeta ﷺ a Medina durante la Hégira?", ["Rabi' al-Awwal", "Ramadán", "Muharram", "Rayab"], "Llegó a Medina en Rabi' al-Awwal, tras detenerse en Quba."),
"sira_138": ("¿Qué pacto hizo Quraysh para aislar a Banu Hashim, que protegían al Profeta ﷺ?", ["Un boicot: sin comercio ni matrimonios con ellos", "Una tregua de diez años", "Un reparto de la Ka'ba", "Una alianza militar"], "Quraysh firmó un pacto de boicot, y Banu Hashim quedaron confinados en un valle durante años."),
"sira_139": ("¿Cómo comenzó el Profeta ﷺ su misión en La Meca, antes de la llamada pública?", ["Llamando discretamente a su círculo cercano", "Con un ejército", "Con una carta a los reyes", "Con una peregrinación"], "Primero llamó en privado a sus parientes y amigos, antes de que la llamada se hiciera pública."),
"sira_140": ("¿Entre qué dos colinas corrió Hayar buscando agua para Isma'il?", ["As-Safa y Al-Marwa", "Uhud y Zawr", "Arafat y Mina", "Hira y Zawr"], "Corrió siete veces entre as-Safa y al-Marwa: el origen del sa'y de los peregrinos."),
"sira_141": ("¿De qué nieto dijo el Profeta ﷺ: «Este hijo mío es un sayyid; Allah reconciliará por él a dos grupos de musulmanes»?", ["Al-Hasan", "Al-Husayn", "Usama", "Ibn Abbas"], "Al-Hasan ibn Ali reconcilió más tarde a dos grandes grupos de musulmanes, como el Profeta ﷺ había anunciado."),
"sira_142": ("¿Cómo se llamaba la hija del Profeta ﷺ, madre de Al-Hasan y Al-Husayn?", ["Fátima", "Zaynab", "Ruqayya", "Umm Kulzum"], "Fátima, esposa de Ali, fue la madre de Al-Hasan y Al-Husayn."),
"sira_143": ("¿Quién era la hija mayor del Profeta ﷺ?", ["Zaynab", "Fátima", "Ruqayya", "Umm Kulzum"], "Zaynab era la mayor de las cuatro hijas del Profeta ﷺ."),
"sira_144": ("¿Qué compañero, antiguo esclavo de origen abisinio, fue elegido almuédano por su hermosa voz?", ["Bilal ibn Rabah", "Salman", "Suhayb", "Zayd"], "Bilal, liberado por Abu Bakr, se convirtió en el almuédano del Profeta ﷺ."),
"sira_145": ("¿De qué compañero dijo el Profeta ﷺ: «Si tomara un amigo íntimo (jalil) entre los hombres, sería él»?", ["Abu Bakr", "Umar", "Ali", "Uzman"], "«Si tomara un amigo íntimo de mi comunidad, tomaría a Abu Bakr, pero es mi hermano y compañero.»"),
"sira_146": ("¿Qué ciudad, junto con La Meca, se llama «al-Haramayn», los dos santuarios?", ["Medina", "Jerusalén", "Ta'if", "Damasco"], "La Meca y Medina son las dos ciudades santas, al-Haramayn."),
"sira_147": ("¿Cuántas veces hizo el Profeta ﷺ el Hayy tras la Hégira?", ["Una, la Peregrinación de Despedida", "Tres veces", "Cada año", "Nunca"], "Solo hizo un Hayy tras la Hégira: la Peregrinación de Despedida, en el año 10."),
"sira_148": ("Según Anas, ¿qué hizo el Profeta ﷺ cuando un beduino tiró con fuerza de su manto exigiendo bienes?", ["Sonrió y ordenó que le dieran algo", "Lo hizo castigar", "Se fue sin decir palabra", "Lo echó"], "El Profeta ﷺ se volvió hacia él, se rió y ordenó que le dieran algo."),
"sira_149": ("¿Qué ciudad, donde está la mezquita al-Aqsa, fue el destino del Viaje Nocturno?", ["Jerusalén", "Damasco", "El Cairo", "Bagdad"], "El Viaje Nocturno llevó al Profeta ﷺ de La Meca a la mezquita al-Aqsa en Jerusalén."),
"sira_150": ("¿Qué edad tenía el Profeta ﷺ al morir?", ["Sesenta y tres", "Cuarenta", "Cincuenta", "Ochenta"], "Murió a los sesenta y tres años, en el año 11 de la Hégira."),
}
